`timescale 1ns/1ps
// Scan test bench for the netlist with the delays of the SDF file. It makes its own clock pulses:
// slow ones to shift, and one or two capture pulses whose distance is GAP periods.
// Each vector row: kind, state, x, clocks, site, fault, good response, expected detection, flags.
//   kind 0: flush the chain with the 8 bits of `state`      kind 1: load, capture, unload
//   clocks 1: one capture   2: launch and capture (launch-on-capture)
//   fault 0: none  1: stuck at 0  2: stuck at 1  3: slow to rise  4: slow to fall
// tf_timing is generated by the runner: the functional period, the SDF annotation, the limits
// of the flops.
// MUTATION 1: the capture comes four periods after the launch, whatever GAP says.
// MUTATION 2: scan_enable is still 1 at the launch, so the launch shifts.
// MUTATION 3 and 4 are in the design.
module tf_tb;
    parameter MUTATION = 0, GAP = 1;
    reg clk = 0, scan_enable = 1, scan_in = 0, x = 0;
    wire scan_out;
    tf_timing t();
    tf_core dut(.*);  // the netlist has no parameters: synthesis already fixed MUTATION
    real shift, gap;
    integer fd, n, i, checks = 0, fault_free = 0, violations_before, site, fault;
    reg [15:0] v[0:8];
    reg [3:0] response, good;
    reg [7:0] sent, seen;
    reg detected;
    reg [11:0] stuck_seen = 0, stuck_hit = 0, slow_seen = 0, slow_hit = 0;
    string vectors, wave;
    task fail(input string label);
        begin $display("CHECK_FAIL %s", label);
              $fatal(1, "row=%0d response=%b good=%b", checks, response, good); end
    endtask
    // Inputs change half a shift period before the rising edge.
    task shift_bit(input reg value);
        begin scan_in = value; #(shift / 2.0) clk = 1; #(shift / 2.0) clk = 0; end
    endtask
    task set_fault(input integer where, input integer what);
        begin
            dut.site_n0.kind = where == 0 ? what : 0; dut.site_n1.kind = where == 1 ? what : 0;
            dut.site_n2.kind = where == 2 ? what : 0; dut.site_n3.kind = where == 3 ? what : 0;
            dut.site_n4.kind = where == 4 ? what : 0; dut.site_n5.kind = where == 5 ? what : 0;
        end
    endtask
    function integer count(input [11:0] bits);
        integer k;
        begin count = 0; for (k = 0; k < 12; k = k + 1) count = count + bits[k]; end
    endfunction
    task flush;
        begin
            sent = v[1][7:0]; scan_enable = 1;
            for (i = 7; i >= 0; i = i - 1) shift_bit(sent[i]);
            // the last four bits are in the chain: the first of them is at scan_out
            for (i = 3; i >= 0; i = i - 1) begin seen[i] = scan_out; shift_bit(1'b0); end
            if ((^seen[3:0]) === 1'bx) fail("TF_X");
            if (seen[3:0] !== sent[3:0]) fail("TF_SHIFT");
            // a chain of another length shows the previous bits at this point
            $display("COVER scan/flush");
        end
    endtask
    task pattern;
        begin
            site = v[4]; fault = v[5]; good = v[6][3:0];
            scan_enable = 1;
            for (i = 3; i >= 0; i = i - 1) shift_bit(v[1][i]);
            scan_in = 0; x = v[2][0];
            if (!(MUTATION == 2 && v[3] == 2)) scan_enable = 0;
            set_fault(site, fault);
            #(shift / 2.0);
            violations_before = timing_pkg::violations;
            if (v[3] == 2) begin
                clk = 1;                                   // launch
                #(gap / 2.0) clk = 0; scan_enable = 0;
                #(gap / 2.0);
            end
            clk = 1;                                       // capture
            #(gap / 2.0) clk = 0;
            #(shift / 2.0);
            set_fault(0, 0);
            scan_enable = 1;
            for (i = 3; i >= 0; i = i - 1) begin response[i] = scan_out; shift_bit(1'b0); end
            detected = response !== good;
            if (fault == 0) begin
                if (timing_pkg::violations != violations_before) fail("TF_TIMING");
                if ((^response) === 1'bx) fail("TF_X");
                if (detected) fail("TF_RESPONSE");
                fault_free = fault_free + 1;
                if (v[3] == 1) $display("COVER capture/single");
                else $display("COVER capture/launch-on-capture");
                if (v[8][0]) $display("COVER launch/node-rises");
                if (v[8][1]) $display("COVER launch/node-falls");
            end else begin
                if (v[7][0] && !detected) fail("TF_ESCAPE");
                if (!v[7][0] && detected) fail("TF_FALSE_ALARM");
                $display("FAULT site=%0d kind=%0d state=%h x=%0d detected=%0d", site, fault, v[1][3:0], v[2][0], detected);
                if (fault <= 2) begin
                    stuck_seen[2 * site + fault - 1] = 1;
                    if (detected) stuck_hit[2 * site + fault - 1] = 1;
                    if (detected && fault == 1) $display("COVER stuck/at-0-detected");
                    if (detected && fault == 2) $display("COVER stuck/at-1-detected");
                end else begin
                    slow_seen[2 * site + fault - 3] = 1;
                    if (detected) slow_hit[2 * site + fault - 3] = 1;
                    if (v[8][2] && fault == 3) $display("COVER transition/slow-to-rise-launched");
                    if (v[8][2] && fault == 4) $display("COVER transition/slow-to-fall-launched");
                    if (v[8][3]) $display("COVER transition/untestable-applied");
                end
            end
        end
    endtask
    initial begin
        if (!$value$plusargs("VECTORS=%s", vectors) || !$value$plusargs("WAVE=%s", wave)) $fatal(1, "arguments required");
        $dumpfile(wave); $dumpvars(0, tf_tb);
        shift = 10.0 * t.PERIOD;
        gap = t.PERIOD * (MUTATION == 1 ? 4 : GAP);
        // a slow node is one functional period late
        dut.site_n0.extra = t.PERIOD; dut.site_n1.extra = t.PERIOD; dut.site_n2.extra = t.PERIOD;
        dut.site_n3.extra = t.PERIOD; dut.site_n4.extra = t.PERIOD; dut.site_n5.extra = t.PERIOD;
        $display("VIEW gap=%0d period=%0.3f", GAP, t.PERIOD);
        fd = $fopen(vectors, "r"); if (!fd) $fatal(1, "vectors missing");
        #(shift);
        while (!$feof(fd)) begin
            n = $fscanf(fd, "%h %h %h %h %h %h %h %h %h\n", v[0], v[1], v[2], v[3], v[4], v[5], v[6], v[7], v[8]);
            if (n != 9) $fatal(1, "bad row");
            if (v[0] == 0) flush; else pattern;
            checks = checks + 1;
        end
        $display("COUNT fault_free=%0d", fault_free);
        $display("COUNT stuck_applied=%0d", count(stuck_seen));
        $display("COUNT stuck_detected=%0d", count(stuck_hit));
        $display("COUNT transition_applied=%0d", count(slow_seen));
        $display("COUNT transition_detected=%0d", count(slow_hit));
        $display("RESULT PASS checks=%0d", checks);
        $finish;
    end
endmodule
